insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000001','yogurt-oats','Greek yogurt protein bowl',array['Breakfast','Snack']::text[],array['Stir the yogurt, oats and chia in a bowl. Add 1–2 tablespoons of water if it feels too thick.','Fold in half the blueberries, then scatter the rest on top. Let stand for 5 minutes for softer oats.']::text[],5,1,false,'{"prep_minutes":5,"cook_minutes":0,"servings":1,"notes":"One bowl. Use plain nonfat yogurt and dry rolled oats.","seasonings":["Cinnamon","Vanilla extract"],"cuisine":"Everyday","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
