insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000002','egg-oats','Egg scramble & apple oatmeal',array['Breakfast']::text[],array['Dice the apple. Simmer the oats and apple in water over low heat for 5–7 minutes, stirring until creamy.','Whisk eggs and whites together. Cook in a nonstick skillet over medium-low heat for 3–5 minutes, folding gently, until fully set (160°F / 71°C for the egg mixture).','Serve the scramble beside the oatmeal.']::text[],10,1,true,'{"prep_minutes":3,"cook_minutes":7,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Cinnamon for oats","Black pepper for eggs"],"cuisine":"Everyday","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
