insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000003','tofu-potatoes','Golden tofu & potato skillet',array['Breakfast','Lunch','Dinner']::text[],array['Dice the potatoes into 1 cm cubes. Microwave with a splash of water, covered loosely, for 5–7 minutes until just tender.','Pat the tofu dry and cut into 2 cm cubes. Heat the measured oil over medium-high heat; brown the tofu for 6–8 minutes, turning to color both sides.','Drain potatoes and add to the skillet. Cook for 4–5 minutes until lightly crisp. Fold in spinach for the final 1–2 minutes, until wilted.']::text[],20,1,true,'{"prep_minutes":5,"cook_minutes":15,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Smoked paprika","Garlic powder","Black pepper"],"cuisine":"Everyday","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
