insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000004','chicken-rice','Lemon-pepper chicken & rice',array['Lunch','Dinner']::text[],array['Rinse the measured dry rice. Add water using the package ratio, bring to a boil, cover and simmer on low for the package cooking time. Rest covered for 5 minutes.','Cut the chicken into even bite-size pieces. Cook in a hot skillet with the measured oil for 7–10 minutes, turning often, until the thickest pieces reach 165°F / 74°C.','Cut broccoli into bite-size florets. Steam for 4–6 minutes until bright green and fork-tender. Serve with rice and chicken.']::text[],30,2,true,'{"prep_minutes":5,"cook_minutes":25,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Lemon zest","Oregano","Black pepper"],"cuisine":"Mediterranean inspired","price_tier":2}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
