insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000005','turkey-potatoes','Smoky turkey & sweet potato bowl',array['Lunch','Dinner']::text[],array['Heat oven to 425°F / 220°C. Dice sweet potato into 1.5 cm cubes, toss with measured oil and roast 20–25 minutes, turning once, until tender.','Cook the turkey over medium-high heat for 7–9 minutes, breaking it into small crumbles, until it reaches 165°F / 74°C.','Steam the frozen vegetables according to the bag, until hot throughout. Spoon turkey and vegetables over sweet potato.']::text[],30,2,true,'{"prep_minutes":5,"cook_minutes":25,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Smoked paprika","Cumin","Chili powder"],"cuisine":"Southwest inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
