insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000006','tuna-bean','Lemon-herb tuna & bean salad',array['Lunch','Dinner']::text[],array['Drain the tuna; rinse and drain the canned beans thoroughly. Wash spinach and pat dry.','Flake tuna into a bowl. Fold in beans, spinach and measured oil without mashing the beans.','Add optional seasonings, toss gently and serve at once.']::text[],10,1,false,'{"prep_minutes":10,"cook_minutes":0,"servings":1,"notes":"Use drained weights for both canned ingredients.","seasonings":["Lemon zest","Dried dill","Black pepper"],"cuisine":"Mediterranean inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
