insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000007','lentil-rice','Warm lentil rice & greens',array['Lunch','Dinner']::text[],array['Rinse the measured dry rice. Add water using the package ratio, bring to a boil, cover and simmer on low for the package cooking time. Rest covered for 5 minutes.','Warm drained cooked lentils with the measured oil and 2 tablespoons of water in a skillet over medium heat for 3–4 minutes.','Add spinach and stir for 1–2 minutes until wilted. Serve over rice.']::text[],20,1,true,'{"prep_minutes":5,"cook_minutes":15,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Cumin","Ground coriander","Black pepper"],"cuisine":"Middle Eastern inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
