insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000008','tofu-rice','Crisp tofu & broccoli rice bowl',array['Lunch','Dinner']::text[],array['Rinse the measured dry rice. Add water using the package ratio, bring to a boil, cover and simmer on low for the package cooking time. Rest covered for 5 minutes.','Pat the tofu dry and cut into 2 cm cubes. Heat the measured oil over medium-high heat; brown the tofu for 6–8 minutes, turning to color both sides.','Steam broccoli for 4–6 minutes until crisp-tender. Add it to the tofu for the last minute, then spoon over rice.']::text[],20,1,true,'{"prep_minutes":5,"cook_minutes":15,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Ground ginger","Garlic powder","Chili flakes"],"cuisine":"East Asian inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
