insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('40000000-0000-4000-8000-000000000009','cottage-fruit','Cottage cheese banana bowl',array['Breakfast','Snack']::text[],array['Peel and slice the banana. Spoon cottage cheese into a bowl.','Arrange banana on top, sprinkle with chia and let stand 2–3 minutes before eating.']::text[],5,1,false,'{"prep_minutes":5,"cook_minutes":0,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Cinnamon"],"cuisine":"Everyday","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
