insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000017','potato-egg-scramble','Potato & pepper egg scramble',array['Breakfast']::text[],array['Dice potato and pepper. Microwave potato with a splash of water for 5–7 minutes until tender.','Heat oil over medium heat. Fry potato and pepper for 4–5 minutes.','Whisk eggs and whites, pour into the skillet and fold gently for 3–5 minutes until fully set (160°F / 71°C).']::text[],20,1,true,'{"prep_minutes":5,"cook_minutes":15,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Paprika","Black pepper"],"cuisine":"Everyday","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
