insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000018','protein-pancakes','Banana oat protein pancakes',array['Breakfast']::text[],array['Blend oats into a coarse flour, then blend with banana and egg whites. Rest the batter 2 minutes.','Heat a nonstick skillet over medium-low heat. Spoon small pancakes into the pan and cook 2–3 minutes per side, until the centers are set and reach 160°F / 71°C.','Serve with yogurt.']::text[],15,2,true,'{"prep_minutes":5,"cook_minutes":10,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Cinnamon","Vanilla extract"],"cuisine":"Everyday","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
