insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000019','chicken-egg-breakfast','Chicken & egg breakfast bowl',array['Breakfast']::text[],array['Dice potatoes and microwave with a splash of water for 6–8 minutes until tender.','Cut the chicken into even bite-size pieces. Cook in a hot skillet with the measured oil for 7–10 minutes, turning often, until the thickest pieces reach 165°F / 74°C.','Add potato and spinach to the pan for 2 minutes. Make a space for the egg and cook until white and yolk are firm. Serve together.']::text[],25,2,true,'{"prep_minutes":5,"cook_minutes":20,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Black pepper","A pinch of salt"],"cuisine":"Everyday","price_tier":2}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
