insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000020','yogurt-toasted-oats','Yogurt with toasted oats & apple',array['Breakfast','Snack']::text[],array['Toast oats in a dry skillet over medium-low heat for 3–4 minutes, stirring until fragrant. Let cool slightly.','Dice apple. Spoon yogurt into a bowl, add apple and toasted oats, and swirl in peanut butter.']::text[],10,1,true,'{"prep_minutes":5,"cook_minutes":5,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Cinnamon"],"cuisine":"Everyday","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
