insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000022','quinoa-egg-bowl','Quinoa egg & greens bowl',array['Breakfast']::text[],array['Rinse quinoa and simmer with package-directed water, covered, until the water is absorbed and the germ curls away, about 15 minutes.','Warm oil in a nonstick pan. Wilt spinach, then add beaten eggs and whites. Fold over medium-low heat until fully set (160°F / 71°C).','Serve the scramble over quinoa.']::text[],25,2,true,'{"prep_minutes":5,"cook_minutes":20,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Black pepper","A pinch of salt"],"cuisine":"Everyday","price_tier":2}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
