insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000023','turkey-bean-chili','Weeknight turkey & bean chili',array['Lunch','Dinner']::text[],array['Dice pepper and carrot. Heat oil in a saucepan and soften vegetables over medium heat for 5 minutes.','Cook the turkey over medium-high heat for 7–9 minutes, breaking it into small crumbles, until it reaches 165°F / 74°C.','Add drained beans, optional spices and 100–150 mL water. Simmer uncovered for 10 minutes until thick and vegetables are tender.']::text[],25,2,true,'{"prep_minutes":5,"cook_minutes":20,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Chili powder","Cumin","Smoked paprika"],"cuisine":"Southwest inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
