insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000024','salmon-quinoa','Dill salmon with quinoa & beans',array['Lunch','Dinner']::text[],array['Heat oven to 400°F / 200°C. Rinse quinoa and simmer using the package water ratio, about 15 minutes.','Place salmon on baking parchment. Roast 12–16 minutes until the center reaches 145°F / 63°C and flakes easily.','Steam green beans 5–7 minutes until tender-crisp. Serve alongside salmon and quinoa.']::text[],30,2,true,'{"prep_minutes":5,"cook_minutes":25,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Dill","Lemon zest","Black pepper"],"cuisine":"Mediterranean inspired","price_tier":3}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
