insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000025','chicken-pasta','Chicken, spinach & pepper pasta',array['Lunch','Dinner']::text[],array['Boil pasta in water according to its package until just tender. Reserve a little cooking water.','Cut the chicken into even bite-size pieces. Cook in a hot skillet with the measured oil for 7–10 minutes, turning often, until the thickest pieces reach 165°F / 74°C.','Slice pepper and add to the chicken for 3 minutes, then wilt in spinach. Toss with pasta and a splash of cooking water.']::text[],25,2,true,'{"prep_minutes":5,"cook_minutes":20,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Basil","Oregano","Garlic powder"],"cuisine":"Italian inspired","price_tier":2}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
