insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000026','turkey-taco-wraps','Turkey & avocado taco wraps',array['Lunch','Dinner']::text[],array['Cook the turkey over medium-high heat for 7–9 minutes, breaking it into small crumbles, until it reaches 165°F / 74°C.','Slice peppers finely and add for the final 3–4 minutes of cooking with optional taco spices.','Warm tortillas in a dry skillet for 20–30 seconds per side. Fill with turkey, peppers and diced avocado.']::text[],20,1,true,'{"prep_minutes":5,"cook_minutes":15,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Cumin","Chili powder","Lime zest"],"cuisine":"Mexican inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
