insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000027','lentil-pasta','Herby lentil & spinach pasta',array['Lunch','Dinner']::text[],array['Boil pasta until just tender using package instructions. Save 3 tablespoons of pasta water.','Warm lentils and oil in a skillet over medium heat for 3 minutes. Add spinach until wilted.','Toss with pasta and reserved water. Season and serve hot.']::text[],20,1,true,'{"prep_minutes":5,"cook_minutes":15,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Oregano","Basil","Garlic powder"],"cuisine":"Italian inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
