insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000028','tofu-peanut-noodles','Peanut tofu noodle bowl',array['Lunch','Dinner']::text[],array['Boil pasta according to the package. Cut tofu into small cubes and grate carrots.','Whisk peanut butter with 2–4 tablespoons of hot pasta water until pourable.','Drain pasta, return to the warm pot and toss with tofu, carrots and peanut sauce over low heat for 2–3 minutes until hot throughout.']::text[],20,2,true,'{"prep_minutes":5,"cook_minutes":15,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Ground ginger","Chili flakes"],"cuisine":"Southeast Asian inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
