insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000029','beef-pepper-rice','Beef & pepper rice skillet',array['Lunch','Dinner']::text[],array['Rinse the measured dry rice. Add water using the package ratio, bring to a boil, cover and simmer on low for the package cooking time. Rest covered for 5 minutes.','Slice the beef into thin strips and pepper into narrow pieces. Heat oil over medium-high heat and brown beef 2–3 minutes per side.','Add pepper and cook until just tender. For intact beef strips, verify 145°F / 63°C and rest 3 minutes; use 160°F / 71°C if substituting ground beef. Serve over rice.']::text[],30,2,true,'{"prep_minutes":5,"cook_minutes":25,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Garlic powder","Smoked paprika"],"cuisine":"Everyday","price_tier":3}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
