insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000031','chicken-sweet-potato-tray','Chicken & sweet potato tray bake',array['Lunch','Dinner']::text[],array['Heat oven to 425°F / 220°C. Dice sweet potatoes into 1.5 cm cubes and toss with half the measured oil on a tray. Roast for 10 minutes.','Add chicken pieces and broccoli with remaining oil. Roast 15–20 minutes more, turning vegetables once.','Check chicken reaches 165°F / 74°C and potatoes are tender before serving.']::text[],35,2,true,'{"prep_minutes":10,"cook_minutes":25,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Rosemary","Garlic powder","Paprika"],"cuisine":"Mediterranean inspired","price_tier":2}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
