insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000032','quinoa-bean-salad','Quinoa, bean & avocado salad',array['Lunch','Dinner']::text[],array['Rinse quinoa and cook with package-directed water until fluffy, about 15 minutes. Spread on a plate to cool briefly.','Rinse and drain beans. Dice pepper and avocado.','Fold everything together gently. Serve warm or cool.']::text[],25,1,true,'{"prep_minutes":5,"cook_minutes":20,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Cumin","Lime zest","Black pepper"],"cuisine":"Southwest inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
