insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000034','loaded-lentil-potato','Loaded lentil baked potato',array['Lunch','Dinner']::text[],array['Scrub and prick potato. Microwave on a plate for 8–12 minutes, turning halfway, until the center is tender.','Warm lentils with a splash of water over medium heat for 3–4 minutes. Stir in spinach until wilted.','Split potato, fluff the center with a fork and spoon over lentils. Finish with yogurt.']::text[],20,1,true,'{"prep_minutes":5,"cook_minutes":15,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Paprika","Black pepper"],"cuisine":"Everyday","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
