insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000035','chicken-veggie-stir-fry','Ginger chicken vegetable stir-fry',array['Lunch','Dinner']::text[],array['Rinse the measured dry rice. Add water using the package ratio, bring to a boil, cover and simmer on low for the package cooking time. Rest covered for 5 minutes.','Cut the chicken into even bite-size pieces. Cook in a hot skillet with the measured oil for 7–10 minutes, turning often, until the thickest pieces reach 165°F / 74°C.','Add frozen vegetables and 2 tablespoons of water, cover for 3–4 minutes, then uncover and stir-fry until hot and tender-crisp. Serve with rice.']::text[],25,2,true,'{"prep_minutes":5,"cook_minutes":20,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Ground ginger","Garlic powder","Chili flakes"],"cuisine":"East Asian inspired","price_tier":2}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
