insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000036','white-bean-spinach-skillet','Creamy bean & spinach skillet',array['Lunch','Dinner']::text[],array['Warm drained beans and measured oil with 60 mL water in a skillet over medium heat for 4–5 minutes.','Mash about a quarter of the beans against the pan to thicken the sauce. Fold in spinach for 1–2 minutes.','Toast bread and serve beside the skillet.']::text[],15,1,true,'{"prep_minutes":5,"cook_minutes":10,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Thyme","Garlic powder","Black pepper"],"cuisine":"Mediterranean inspired","price_tier":1}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
