insert into public.meals(id,slug,name,slots,instructions,cooking_minutes,complexity,batch_friendly,recipe) values('41000000-0000-4000-8000-000000000037','salmon-potatoes','Paprika salmon & crushed potatoes',array['Lunch','Dinner']::text[],array['Heat oven to 400°F / 200°C. Dice potatoes and boil in water for 12–15 minutes until tender.','Bake salmon on parchment for 12–16 minutes, until it reaches 145°F / 63°C and flakes easily.','Steam broccoli 4–6 minutes. Lightly crush drained potatoes with a fork and serve with fish and broccoli.']::text[],30,2,true,'{"prep_minutes":5,"cook_minutes":25,"servings":1,"notes":"Weights refer to the ingredient form shown. Water and optional dry seasonings add no tracked portions.","seasonings":["Paprika","Lemon zest"],"cuisine":"Everyday","price_tier":3}'::jsonb) on conflict(slug) do update set name=excluded.name,slots=excluded.slots,instructions=excluded.instructions,cooking_minutes=excluded.cooking_minutes,complexity=excluded.complexity,batch_friendly=excluded.batch_friendly,recipe=excluded.recipe;
